<?php
declare(strict_types=1);
require_once __DIR__.'/config/communications_step21.php';
$error=null;$msg=null;$rows=[];$filter=(string)($_GET['status']??'all');
try{$pdo=business_db();comm_step21_ensure($pdo);$user=security_step17_current_user($pdo);$ctx=comm_step21_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){$action=(string)($_POST['action']??'');if($action==='dispatch'){$r=comm_step21_dispatch($pdo,$orgId,50);$msg='Dispatcher processed '.$r['processed'].' item(s): '.$r['sent'].' sent, '.$r['failed'].' failed.';}else{comm_step21_outbox_action($pdo,$orgId,(int)($_POST['id']??0),$action,(int)$user['id']);$msg='Outbox item updated.';}}$allowed=['all','queued','manual_ready','waiting_provider','sent','failed','cancelled'];if(!in_array($filter,$allowed,true))$filter='all';$sql="SELECT o.*,t.template_name FROM communication_outbox o LEFT JOIN communication_templates t ON t.id=o.template_id WHERE o.organization_id=?";$args=[$orgId];if($filter!=='all'){$sql.=' AND o.status=?';$args[]=$filter;}$sql.=' ORDER BY o.id DESC LIMIT 250';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Communication Outbox - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="communication_center.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>Communication Outbox</small></span></a><div class="os-top-actions"><a class="os-btn" href="communication_compose.php">Compose</a><a class="os-btn primary" href="communication_center.php">Communications</a></div></div></header><main class="os-main" style="max-width:1420px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">STEP 21 • OUTBOX</div><h1>Every external communication has a delivery state.</h1><p>Queued webhook items can be dispatched; manual items open the device/app and require an explicit Mark Sent action. Failed items retain attempt evidence.</p></section><?php if($error):?><div class="pp-alert bad"><?=comm_step21_h($error)?></div><?php endif;?><?php if($msg):?><div class="pp-alert good"><?=comm_step21_h($msg)?></div><?php endif;?><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2>Outbox</h2><p><?=count($rows)?> item(s) in current view.</p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><form method="post"><input type="hidden" name="action" value="dispatch"><button class="os-btn">Run Dispatcher</button></form><a class="os-btn" href="communication_history.php">History</a></div></div><div class="pp-filterbar"><?php foreach(['all','queued','manual_ready','waiting_provider','sent','failed','cancelled'] as $st):?><a class="pp-chip <?=$filter===$st?'active':''?>" href="?status=<?=$st?>"><?=strtoupper(str_replace('_',' ',$st))?></a><?php endforeach;?></div><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>ID</th><th>Channel / Status</th><th>Recipient</th><th>Message</th><th>Schedule</th><th>Attempts</th><th>Actions</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7">No outbox items.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><b><?=comm_step21_h(strtoupper((string)$r['channel']))?></b><br><span class="pp-badge <?=in_array($r['status'],['failed','waiting_provider'],true)?'warn':''?>"><?=comm_step21_h(strtoupper(str_replace('_',' ',(string)$r['status'])))?></span></td><td><b><?=comm_step21_h($r['recipient_name_snapshot']?:$r['recipient_type'])?></b><br><small><?=comm_step21_h($r['recipient_address_snapshot'])?></small></td><td><?php if($r['subject_snapshot']):?><b><?=comm_step21_h($r['subject_snapshot'])?></b><br><?php endif;?><small><?=comm_step21_h(strlen((string)$r['body_snapshot'])>180?substr((string)$r['body_snapshot'],0,180).'…':$r['body_snapshot'])?></small><?php if($r['last_error']):?><br><small style="color:#9c2f2f"><?=comm_step21_h($r['last_error'])?></small><?php endif;?></td><td><?=comm_step21_h($r['scheduled_at'])?><br><small><?=$r['sent_at']?'Sent '.$r['sent_at']:''?></small></td><td><?=$r['attempts']?> / <?=$r['max_attempts']?></td><td><div style="display:flex;gap:6px;flex-wrap:wrap"><?php if($r['status']==='manual_ready'):?><a class="os-btn" target="_blank" rel="noopener" href="<?=comm_step21_h(comm_step21_manual_url($r))?>">Open <?=comm_step21_h(ucfirst((string)$r['channel']))?></a><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="mark_sent"><button class="os-btn">Mark Sent</button></form><?php endif;?><?php if(in_array($r['status'],['failed','waiting_provider'],true)):?><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="retry"><button class="os-btn">Retry</button></form><?php endif;?><?php if(!in_array($r['status'],['sent','cancelled'],true)):?><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="cancel"><button class="os-btn">Cancel</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section></main><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
